package com.vandorlabs.neoforge.navigation;
import java.util.*;
import com.vandorlabs.navigation.NavigationLayout;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.tick.LevelTickEvent;
/** Bounded complete-component scans deferred until after chunk installation. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeNavigationTableAssemblies {
 private static final Map<ServerLevel,Set<BlockPos>> PENDING=new WeakHashMap<>();
 public static void queue(NativeNavigationTableEntity t){if(t.getLevel() instanceof ServerLevel l)PENDING.computeIfAbsent(l,k->new LinkedHashSet<>()).add(t.getBlockPos());}
 public static void queue(net.minecraft.world.level.Level l,BlockPos p){if(l instanceof ServerLevel s)PENDING.computeIfAbsent(s,k->new LinkedHashSet<>()).add(p.immutable());}
 @SubscribeEvent public static void tick(LevelTickEvent.Post event){if(!(event.getLevel() instanceof ServerLevel l))return;var pending=PENDING.remove(l);if(pending==null)return;var done=new HashSet<BlockPos>();for(var p:pending)if(!done.contains(p)&&l.hasChunkAt(p)&&l.getBlockEntity(p) instanceof NativeNavigationTableEntity t)rebuild(t,done);}
 public static void rebuild(NativeNavigationTableEntity start,Set<BlockPos> done){var level=start.getLevel();if(level==null||level.isClientSide||start.inert())return;if(com.vandorlabs.neoforge.gear.NativeGearHolds.reserved(level,start.getBlockPos())||com.vandorlabs.neoforge.transfer.NativeTransferHolds.reserved(level,start.getBlockPos())){queue(start);return;}var members=new LinkedHashMap<BlockPos,NativeNavigationTableEntity>();var queue=new ArrayDeque<BlockPos>();queue.add(start.getBlockPos());boolean complete=true;var face=start.getBlockState().getValue(NativeNavigationTableBlock.FACING);
  while(!queue.isEmpty()){var p=queue.remove();if(members.containsKey(p))continue;if(!level.hasChunkAt(p)){complete=false;continue;}if(com.vandorlabs.neoforge.gear.NativeGearHolds.reserved(level,p)||com.vandorlabs.neoforge.transfer.NativeTransferHolds.reserved(level,p)){complete=false;queue(start);continue;}if(level.getBlockState(p).getBlock() instanceof NativeNavigationTableBlock block&&block.kind==start.kind()&&(start.kind()==NavigationLayout.Kind.FLAT||level.getBlockState(p).getValue(NativeNavigationTableBlock.FACING)==face)&&(!(level.getBlockEntity(p) instanceof NativeNavigationTableEntity candidate)||candidate.inert())){complete=false;continue;}if(!(level.getBlockEntity(p) instanceof NativeNavigationTableEntity t)||t.inert()||t.kind()!=start.kind()||start.kind()==NavigationLayout.Kind.ANGLED&&t.getBlockState().getValue(NativeNavigationTableBlock.FACING)!=face)continue;members.put(p,t);if(members.size()>256){complete=false;break;}for(var d:Direction.Plane.HORIZONTAL){if(start.kind()==NavigationLayout.Kind.ANGLED&&d.getAxis()==face.getAxis())continue;queue.add(p.relative(d));}}
  done.addAll(members.keySet());if(!complete)return;
  NavigationLayout.Layout layout;try{var cells=new LinkedHashMap<NavigationLayout.Cell,NavigationLayout.Facing>();members.forEach((p,t)->cells.put(NativeNavigationTableEntity.cell(p),NativeNavigationTableEntity.facing(t.getBlockState().getValue(NativeNavigationTableBlock.FACING))));layout=start.kind()==NavigationLayout.Kind.FLAT?NavigationLayout.mixedFlat(cells,true):NavigationLayout.build(start.kind(),NativeNavigationTableEntity.facing(face),cells.keySet(),true);}catch(IllegalArgumentException invalid){members.values().forEach(t->t.invalid(true));return;}
  var owner=NativeNavigationTableEntity.pos(layout.chipOwner);var ordered=new ArrayList<>(members.values());ordered.sort(Comparator.<NativeNavigationTableEntity>comparingDouble(t->t.getBlockPos().distSqr(owner)).thenComparingLong(t->t.getBlockPos().asLong()));var chip=ordered.stream().filter(t->!t.storedChip().isEmpty()).findFirst().orElse(members.get(owner));for(var t:ordered)if(t!=chip&&!t.storedChip().isEmpty())t.ejectChip();NativeNavigationTableEntity bay=ordered.stream().filter(t->!t.getBlockPos().equals(owner)).findFirst().orElse(null);var storage=ordered.stream().filter(t->!t.storedModule().isEmpty()).findFirst().orElse(bay==null?members.get(owner):bay);for(var t:ordered)if(t!=storage&&!t.storedModule().isEmpty())t.ejectModule();if(bay==null)storage.ejectModule();var bayFace=bay==null?face:bay.getBlockState().getValue(NativeNavigationTableBlock.FACING);if(bay!=null&&members.containsKey(bay.getBlockPos().relative(bayFace)))for(var d:Direction.Plane.HORIZONTAL)if(!members.containsKey(bay.getBlockPos().relative(d))){bayFace=d;break;}
  var configured=ordered.stream().max(Comparator.comparingInt(NativeNavigationTableEntity::settingsPriority)).orElse(start);var previous=configured.reader();if(previous==null||!members.containsValue(previous))previous=configured;for(var member:members.values())member.inheritSettings(previous);
  for(var t:members.values())t.layout(layout,layout.tiles.get(NativeNavigationTableEntity.cell(t.getBlockPos())),chip.getBlockPos(),storage.getBlockPos(),bay==null?null:bay.getBlockPos(),bayFace);
  var current=members.get(owner);if(previous!=current)NativeNavigationTableHooks.TABLE.reparent(previous,current);for(var member:members.values()){com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.unregister(member);com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.queueRegistration(member);}
 }
 private NativeNavigationTableAssemblies(){}
}
